def seed_questions():
    db = SessionLocal()

    try:
        added = 0
        skipped = 0

        for item in QUESTIONS:
            existing = (
                db.query(Question)
                .filter(Question.question_text == item["question_text"])
                .first()
            )

            if existing:
                skipped += 1
                continue

            question = Question(
                section=AssessmentSection[item["section"]],
                question_text=item["question_text"],
                option_a=item["option_a"],
                option_b=item["option_b"],
                option_c=item["option_c"],
                option_d=item["option_d"],
                correct_option=item["correct_option"],
                difficulty=DifficultyLevel[item["difficulty"]],
                expected_time_seconds=item["expected_time_seconds"],
                positive_mark=1.0,
                negative_mark=0.25,
                is_active=True,
            )

            db.add(question)
            added += 1

        db.commit()

        print(f"Questions added: {added}")
        print(f"Questions already present: {skipped}")

        for section in AssessmentSection:
            count = (
                db.query(Question)
                .filter(
                    Question.section == section,
                    Question.is_active == True
                )
                .count()
            )
            print(f"{section.value}: {count} active questions")

    except Exception:
        db.rollback()
        raise

    finally:
        db.close()


if __name__ == "__main__":
    seed_questions()
